(()=>{
 const input=document.querySelector('#fileInput'), drop=document.querySelector('#dropzone'), preview=document.querySelector('#sourcePreview'), imagePreview=document.querySelector('#imagePreview'), remove=document.querySelector('#removeImage'), count=document.querySelector('#colorCount'), colorValue=document.querySelector('#colorValue'), detail=document.querySelector('#detailLevel'), detailValue=document.querySelector('#detailValue'), make=document.querySelector('#vectorizeBtn'), download=document.querySelector('#downloadBtn'), resultImg=document.querySelector('#resultPreview'), resultVisual=document.querySelector('.result-visual'), resultMeta=document.querySelector('#resultMeta'), resultStatus=document.querySelector('#resultStatus');
 let source=null, sourceFile=null, sourceName='artwork', resultUrl=null, vectorData=null, vectorSize={w:0,h:0}, apiMode=false, localFallback=false;
 const studio=document.querySelector('.studio'), toolHeading=document.querySelector('.tool-section .section-heading'), toolWrap=studio.parentElement;
 const toolDisclaimer=document.querySelector('.tool-disclaimer'), defaultDisclaimer=toolDisclaimer?.textContent||'';
 const resultScreen=document.createElement('section');resultScreen.id='resultScreen';resultScreen.className='result-screen';resultScreen.hidden=true;studio.insertAdjacentElement('afterend',resultScreen);
 const detailNames={'360':'Clean & simple','560':'Balanced','760':'Fine detail'};
 count.addEventListener('input',()=>colorValue.textContent=`${count.value} colors`);
 detail.addEventListener('change',()=>detailValue.textContent=detailNames[detail.value]);
 let fileSequence=0;
 const setFile=file=>{if(activeRequest||!file)return;if(!/^image\/(png|jpeg|webp|gif|bmp)$/.test(file.type)){alert('Choose a PNG, JPG, WebP, GIF, or BMP image.');return}if(file.size>4*1024*1024){alert('This image is over 4 MB. Choose a smaller file to continue.');return}const sequence=++fileSequence;const reader=new FileReader();reader.onerror=()=>{document.querySelector('#conversionMessage').textContent='Could not read this image. Please choose it again.'};reader.onload=()=>{const img=new Image();img.onerror=()=>{document.querySelector('#conversionMessage').textContent='This image could not be opened. Try a PNG or JPG file.'};img.onload=()=>{if(sequence!==fileSequence)return;source=img;sourceFile=file;apiMode=false;localFallback=false;if(toolDisclaimer)toolDisclaimer.textContent=defaultDisclaimer;sourceName=(file.name||'artwork').replace(/\.[^.]+$/,'').replace(/[^a-z0-9_-]+/gi,'-').toLowerCase()||'artwork';preview.src=reader.result;imagePreview.classList.add('visible');if(heroDrop){heroDrop.classList.add('has-image');document.querySelector('#heroSelectedPreview').src=reader.result;document.querySelector('#heroDropCopy strong').textContent='Image ready to vectorize';document.querySelector('#heroDropCopy small').textContent=file.name||'Your image is ready'}make.disabled=false;resultVisual.classList.remove('has-result','loading');resultStatus.textContent='READY TO TRACE';resultMeta.textContent=`${img.naturalWidth} × ${img.naturalHeight} px · Image selected`;download.classList.add('disabled');download.setAttribute('aria-disabled','true');if(resultUrl){URL.revokeObjectURL(resultUrl);resultUrl=null}resultScreen.hidden=true;document.querySelector('#conversionResults').hidden=true;document.querySelector('#retryVector').hidden=false;input.value='';traceWithApi()};img.src=reader.result};reader.readAsDataURL(file)};
 input.addEventListener('change',e=>setFile(e.target.files[0]));const heroDrop=document.querySelector('#heroDropzone');document.querySelector('#heroPick')?.addEventListener('click',()=>input.click());if(heroDrop){['dragenter','dragover'].forEach(type=>heroDrop.addEventListener(type,e=>{e.preventDefault();heroDrop.classList.add('dragover')}));['dragleave','drop'].forEach(type=>heroDrop.addEventListener(type,e=>{e.preventDefault();heroDrop.classList.remove('dragover')}));heroDrop.addEventListener('drop',e=>setFile(e.dataTransfer.files[0]))}document.addEventListener('paste',e=>{const item=[...(e.clipboardData?.items||[])].find(x=>x.type.startsWith('image/'));if(item){const file=item.getAsFile();if(file)setFile(file)}});['dragenter','dragover'].forEach(type=>drop.addEventListener(type,e=>{e.preventDefault();drop.classList.add('dragover')}));['dragleave','drop'].forEach(type=>drop.addEventListener(type,e=>{e.preventDefault();drop.classList.remove('dragover')}));drop.addEventListener('drop',e=>setFile(e.dataTransfer.files[0]));
 remove.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();source=null;input.value='';imagePreview.classList.remove('visible');heroDrop?.classList.remove('has-image');document.querySelector('#heroDropCopy strong').textContent='Drag an image here to begin';document.querySelector('#heroDropCopy small').textContent='Drop your file anywhere in this area';make.disabled=true;resultVisual.classList.remove('has-result');resultStatus.textContent='WAITING FOR IMAGE';resultMeta.textContent='SVG · Ready when you are';download.classList.add('disabled');download.setAttribute('aria-disabled','true')});
 const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const showResults=()=>{
 document.querySelector('#conversionResults').hidden=false;
 resultScreen.hidden=false;
 resultScreen.innerHTML=`<div class="result-head"><div><span class="result-kicker">YOUR VECTOR PREVIEW</span><h2>See the difference.</h2><p>Drag the divider to compare your original image with the vector preview.</p></div></div><div class="paid-preview" style="--split:50%"><img class="preview-after" src="${resultUrl}" alt="Vector preview"><img class="preview-before" src="${source.src}" alt="Original image"><span class="preview-divider" aria-hidden="true">↔</span><input type="range" min="0" max="100" value="50" aria-label="Compare original and vector preview"><span class="preview-label before">Original</span><span class="preview-label after">Vector preview</span></div><div class="result-footer"><div><strong>Download with a subscription</strong><small>US$4.99/month · 10 conversions each month. Sign in to use your monthly conversions.</small></div><a class="result-primary" href="/account/" target="_blank" rel="noopener">Sign in / manage account</a><button class="result-primary" id="paidDownload" hidden>Download SVG · 1 conversion</button><p id="downloadMessage" role="status"></p><button class="text-reset" id="pickAnother">Choose another image</button></div>`;
 const slider=resultScreen.querySelector('input');slider.addEventListener('input',()=>slider.parentElement.style.setProperty('--split',slider.value+'%'));
 refreshDownload();
 resultScreen.querySelector('#paidDownload').addEventListener('click',downloadPaid);
 resultScreen.querySelector('#pickAnother').addEventListener('click',()=>input.click());
 };
 const apiForm=(file,format,purpose='preview')=>{const form=new FormData();form.append('image',file,file.name||'image.png');form.append('output.file_format',format);form.append('processing.max_colors',String(Number(count.value)));form.append('input.max_pixels',String(detail.value==='360'?500000:detail.value==='560'?2000000:3140000));form.append('purpose',purpose);if(purpose==='download')form.append('request_id',crypto.randomUUID());const preset=document.querySelector('[data-preset].selected')?.dataset.preset||'general',draw=document.querySelector('#advDraw')?.value||(preset==='cut'?'outline':'filled'),group=document.querySelector('#advGroup')?.value||(preset==='edit'?'color':'none');form.append('output.draw_style',draw==='outline'?'stroke_edges':'fill_shapes');form.append('output.shape_stacking',preset==='edit'?'stacked':'cutouts');form.append('output.group_by',group);form.append('output.gap_filler.enabled',draw==='outline'?'false':'true');if(draw==='outline')form.append('output.strokes.stroke_width',String(Number(document.querySelector('#advStroke')?.value||1)));return form};
 let activeRequest=null, loaderFocus=null;
 const loader=document.createElement('dialog');
 loader.className='conversion-loader';
 loader.setAttribute('aria-labelledby','loaderTitle');
 loader.innerHTML=`<h2 id="loaderTitle">Creating your vector</h2><div class="loader-stages">${['Upload','Process','Fetch'].map((name,i)=>`<div class="loader-row"><label for="loaderStage${i}">${name}</label><progress id="loaderStage${i}" max="100" value="0" aria-label="${name}"></progress></div>`).join('')}</div><p id="loaderStatus" role="status" aria-live="polite">Uploading your image…</p><div class="loader-footer"><button type="button" id="cancelConversion">Cancel</button></div>`;
 document.body.append(loader);
 const stages=[...loader.querySelectorAll('progress')];
 const stage=(index,value)=>{if(value===null)stages[index].removeAttribute('value');else stages[index].value=value;};
 const cancel=()=>activeRequest?.abort();
 loader.querySelector('button').addEventListener('click',cancel);
 loader.addEventListener('cancel',e=>{e.preventDefault();cancel()});
 const callVectorizer=(file,format,purpose='preview')=>new Promise((resolve,reject)=>{
   if(!file){reject(Error('Choose an image first.'));return}
   if(activeRequest){reject(Error('A conversion is already running.'));return}
   const xhr=new XMLHttpRequest();activeRequest=xhr;loaderFocus=document.activeElement;
   stages.forEach(p=>p.value=0);stage(0,null);loader.querySelector('#loaderStatus').textContent='Uploading your image…';loader.showModal();
   const finish=()=>{activeRequest=null;loader.close();if(loaderFocus?.isConnected)loaderFocus.focus()};
   xhr.open('POST','/api/vectorize');xhr.responseType='blob';xhr.timeout=70000;
   xhr.upload.onprogress=e=>{if(e.lengthComputable)stage(0,e.loaded/e.total*100)};
   xhr.upload.onload=()=>{stage(0,100);stage(1,null);loader.querySelector('#loaderStatus').textContent='Processing your image…'};
   xhr.onprogress=e=>{stage(0,100);stage(1,100);stage(2,e.lengthComputable?e.loaded/e.total*100:null);loader.querySelector('#loaderStatus').textContent='Fetching your vector…'};
   xhr.onload=async()=>{
     if(xhr.status<200||xhr.status>=300){let message=`Vectorizer API returned ${xhr.status}.`;try{const data=JSON.parse(await xhr.response.text());message=data.error||data.message||message}catch{}const error=Error(message);error.status=xhr.status;finish();reject(error);return}
     stages.forEach(p=>p.value=100);finish();resolve(xhr.response);
   };
   xhr.onerror=()=>{finish();reject(Error('The connection was interrupted. Please try again.'))};
   xhr.ontimeout=()=>{finish();reject(Error('This conversion took too long. Please try again.'))};
   xhr.onabort=()=>{finish();reject(new DOMException('Conversion cancelled.','AbortError'))};
   try{xhr.send(apiForm(file,format,purpose))}catch(error){finish();reject(error)}
 });

 const refreshDownload=async()=>{try{const response=await fetch('/api/account',{cache:'no-store'});if(!response.ok)return;const state=await response.json();const button=resultScreen.querySelector('#paidDownload');if(button)button.hidden=!(state.user&&state.billingReady&&state.billing?.remaining>0);}catch{}};
 window.addEventListener('focus',refreshDownload);
 const downloadPaid=async()=>{const button=resultScreen.querySelector('#paidDownload'),message=resultScreen.querySelector('#downloadMessage');if(!sourceFile||activeRequest)return;button.disabled=true;message.textContent='';try{const blob=await callVectorizer(sourceFile,'svg','download');const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=sourceName+'.svg';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);message.textContent='Your SVG is ready. Save it now; we do not keep a file library.';await refreshDownload();}catch(error){message.textContent=error.name==='AbortError'?'Download cancelled. Refresh your account to check your remaining conversions.':error.message;}finally{button.disabled=false}};
 document.querySelector('#retryVector').addEventListener('click',()=>traceWithApi());
 const traceWithApi=async()=>{if(!sourceFile||activeRequest)return;document.querySelector('#conversionMessage').textContent='';localFallback=false;make.disabled=true;make.textContent='Vectorizing with Vectorizer.AI…';resultVisual.classList.add('loading');resultStatus.textContent='SENDING VECTORIZE REQUEST';try{const blob=await callVectorizer(sourceFile,'png');apiMode=true;vectorData=null;if(toolDisclaimer)toolDisclaimer.textContent=defaultDisclaimer;if(resultUrl)URL.revokeObjectURL(resultUrl);resultUrl=URL.createObjectURL(blob);resultImg.src=resultUrl;resultVisual.classList.add('has-result');resultVisual.classList.remove('loading');resultStatus.textContent='VECTOR PREVIEW READY';resultMeta.textContent=`Vectorizer.AI · ${source.naturalWidth} × ${source.naturalHeight} px`;showResults(Number(count.value),0);resultScreen.scrollIntoView({behavior:'smooth',block:'start'})}catch(err){resultVisual.classList.remove('loading');resultStatus.textContent='READY TO RETRY';document.querySelector('#conversionMessage').textContent=err.name==='AbortError'?'Conversion cancelled. You can try again or choose another image.':(err.message||'Could not convert this image. Please try again.');}finally{if(!localFallback){make.disabled=false;make.innerHTML='Make my vector <span>✳</span>'}}};
 make.addEventListener('click',traceWithApi);document.querySelectorAll('.faq-list details').forEach(d=>d.addEventListener('toggle',()=>{const s=d.querySelector('summary span');if(s)s.textContent=d.open?'×':'+'}));const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('.nav');menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open))});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}));
})();
